"use client";
import { useEffect } from "react";

/**
 * Registers the offline service worker in static (installable) builds.
 * sw.js is generated by scripts/gen-sw.mjs with the full list of built files,
 * so after the first visit the whole game works without a connection.
 */
export function PwaRegister() {
  useEffect(() => {
    if (process.env.NEXT_PUBLIC_PWA !== "1" || !("serviceWorker" in navigator)) return;
    const base = process.env.NEXT_PUBLIC_BASE_PATH ?? "";
    navigator.serviceWorker.register(`${base}/sw.js`, { scope: `${base}/` }).catch((e) => console.warn("service worker:", e));
  }, []);
  return null;
}
